        Expect(string.Equals(portugueseSectionProperties.First(property => string.Equals(property.Name, "OBJECTCOUNT", StringComparison.Ordinal)).GetValue(portugueseSelection)?.ToString(), "0", StringComparison.Ordinal) &&
