        Expect(string.Equals(pseudoSectionProperties.First(property => string.Equals(property.Name, "EXPRESSIONFIELD", StringComparison.Ordinal)).GetValue(pseudoSelection)?.ToString(), "3", StringComparison.Ordinal) &&
