                    expectUnplacedObject: false,
                    "reloaded undone real asset editor snap-horizontal snapshot should preserve original HPOS");
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterUndo.Document,
                    recordIndex,
                    "VPOS",
                    expectedOriginalRawVpos,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded undone real asset editor snap-horizontal snapshot should preserve original VPOS");

                var reloadedSection = reloadedAfterUndo.Document.ReportLayout?.Sections
                    .FirstOrDefault(candidate => candidate.RecordIndex == expectedSectionRecordIndex);
                var reloadedLayoutObject = reloadedSection?.Objects
                    .FirstOrDefault(candidate => candidate.RecordIndex == recordIndex);
                Expect(reloadedLayoutObject is not null,
                    $"reloaded undone real asset editor snap-horizontal snapshot should preserve layout object {recordIndex} for {sourcePath}");
                if (reloadedLayoutObject is not null)
                {
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "HPOS") == expectedOriginalLayoutHpos,
                        $"reloaded undone real asset editor snap-horizontal snapshot should expose layout HPOS={expectedOriginalLayoutHpos} for {sourcePath}");
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "VPOS") == expectedOriginalLayoutVpos,
                        $"reloaded undone real asset editor snap-horizontal snapshot should expose layout VPOS={expectedOriginalLayoutVpos} for {sourcePath}");
                }
            }

            TearDownForm(hostForm);
        }
        finally
        {
            try
            {
                if (Directory.Exists(tempRoot))
                {
                    Directory.Delete(tempRoot, recursive: true);
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }

    private static void SmokeAssetEditorSnapToGridCommandWithRealAsset(
        string? sourcePath,
        int recordIndex,
        string expectedSectionTitle,
        int expectedSectionRecordIndex,
        string expectedObjectTitle,
        int expectedSectionCount,
        bool expectLabel,
        string expectedUniqueId,
        string expectedOriginalRawHpos,
        string expectedOriginalRawVpos,
        string expectedUpdatedRawHpos,
        string expectedUpdatedRawVpos,
        int expectedOriginalLayoutHpos,
        int expectedOriginalLayoutVpos,
        int expectedUpdatedLayoutHpos,
        int expectedUpdatedLayoutVpos)
    {
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
        {
            Console.WriteLine($"SKIP: {(string.IsNullOrWhiteSpace(sourcePath) ? "real asset editor snap-to-grid candidate" : sourcePath)} not found.");
            return;
        }

        var tempRoot = Path.Combine(Path.GetTempPath(), "CopperfinDesignerSmokeRealAssetEditorSnapToGrid-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tempRoot);
        var assetPath = CreateWritableAssetCopy(sourcePath!, tempRoot);

        try
        {
            using var hostForm = new Form
            {
                Width = 1400,
                Height = 1000,
                ShowInTaskbar = false,
                StartPosition = FormStartPosition.Manual,
                Location = new Point(-32000, -32000)
            };

            using var control = new CopperfinAssetEditorControl
            {
                Dock = DockStyle.Fill
            };

            hostForm.Controls.Add(control);
            hostForm.Show();
            Application.DoEvents();
            control.LoadDocument(assetPath);

            var sectionListView = GetPrivateListView(control, "sectionListView");
            var objectListView = GetPrivateListView(control, "objectListView");
            var propertyGrid = GetPrivatePropertyGrid(control);
            var snapToGridButton = GetPrivateButton(control, "snapToGridObjectButton");
            var deleteButton = GetPrivateButton(control, "deleteObjectButton");
            var restoreButton = GetPrivateButton(control, "restoreObjectButton");
            var surface = FindDesignSurface(control) ?? throw new InvalidOperationException("Could not find shared report design surface for the real snap-to-grid smoke.");

            var loaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => sectionListView.Items.Count > 0);
            Expect(loaded, $"real asset editor snap-to-grid smoke should load section data for {sourcePath}");
            if (!loaded)
            {
                return;
            }

            foreach (ListViewItem item in sectionListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioReportSection section &&
                                section.RecordIndex == expectedSectionRecordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncExplorerSelection");
            Application.DoEvents();

            var objectLoaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => objectListView.Items.Cast<ListViewItem>()
                    .Any(item => item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                 snapshotObject.RecordIndex == recordIndex));
            Expect(objectLoaded, $"real asset editor snap-to-grid smoke should surface object {recordIndex} for {sourcePath}");
            if (!objectLoaded)
            {
                return;
            }

            foreach (ListViewItem item in objectListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                snapshotObject.RecordIndex == recordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncSelectionFromList");
            Application.DoEvents();

            Expect(snapToGridButton.Visible &&
                   snapToGridButton.Enabled &&
                   deleteButton.Visible &&
                   deleteButton.Enabled &&
                   !restoreButton.Visible &&
                   propertyGrid.SelectedObject is CopperfinDesignerSelection initialSelection &&
                   initialSelection.RecordIndex == recordIndex &&
                   string.Equals(ReadSelectionPropertyValue(initialSelection, "HPOS"), expectedOriginalLayoutHpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal) &&
                   string.Equals(ReadSelectionPropertyValue(initialSelection, "VPOS"), expectedOriginalLayoutVpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal),
                $"real asset editor snap-to-grid smoke should start from a live object selection with original geometry exposed for {sourcePath}");

            snapToGridButton.PerformClick();
            Application.DoEvents();

            var snappedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != recordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == expectedSectionRecordIndex &&
                           selectedObject?.RecordIndex == recordIndex &&
                           !selectedObject.Deleted &&
                           string.Equals(selectedObject.Title, expectedObjectTitle, StringComparison.Ordinal) &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), expectedUniqueId, StringComparison.Ordinal) &&
                           string.Equals(ReadSelectionPropertyValue(refreshedSelection, "HPOS"), expectedUpdatedLayoutHpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal) &&
                           string.Equals(ReadSelectionPropertyValue(refreshedSelection, "VPOS"), expectedUpdatedLayoutVpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal) &&
                           string.Equals(objectState, "Live", StringComparison.Ordinal) &&
                           snapToGridButton.Visible &&
                           snapToGridButton.Enabled &&
                           deleteButton.Visible &&
                           deleteButton.Enabled &&
                           !restoreButton.Visible &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == recordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == expectedSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(snappedSelection,
                $"real asset editor snap-to-grid smoke should preserve live section/object continuity after snapping for {sourcePath}");
            Expect(control.CanHandleUndoCommand(),
                $"real asset editor snap-to-grid smoke should expose undo after snapping for {sourcePath}");
            if (!snappedSelection)
            {
                return;
            }

            var reloadedAfterSnap = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterSnap.Success && reloadedAfterSnap.Document is not null,
                $"real asset editor snap-to-grid smoke should reload snapped on-disk state for {sourcePath}");
            if (reloadedAfterSnap.Success && reloadedAfterSnap.Document is not null)
            {
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterSnap.Document,
                    recordIndex,
                    "HPOS",
                    expectedUpdatedRawHpos,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded real asset editor snap-to-grid snapshot should preserve HPOS");
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterSnap.Document,
                    recordIndex,
                    "VPOS",
                    expectedUpdatedRawVpos,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded real asset editor snap-to-grid snapshot should preserve VPOS");

                var reloadedSection = reloadedAfterSnap.Document.ReportLayout?.Sections
                    .FirstOrDefault(candidate => candidate.RecordIndex == expectedSectionRecordIndex);
                var reloadedLayoutObject = reloadedSection?.Objects
                    .FirstOrDefault(candidate => candidate.RecordIndex == recordIndex);
                Expect(reloadedLayoutObject is not null,
                    $"reloaded real asset editor snap-to-grid snapshot should preserve layout object {recordIndex} for {sourcePath}");
                if (reloadedLayoutObject is not null)
                {
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "HPOS") == expectedUpdatedLayoutHpos,
                        $"reloaded real asset editor snap-to-grid snapshot should expose layout HPOS={expectedUpdatedLayoutHpos} for {sourcePath}");
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "VPOS") == expectedUpdatedLayoutVpos,
                        $"reloaded real asset editor snap-to-grid snapshot should expose layout VPOS={expectedUpdatedLayoutVpos} for {sourcePath}");
                }
            }

            var undoHandled = control.TryHandleUndoCommand();
            Expect(undoHandled,
                $"real asset editor snap-to-grid smoke should execute undo after snapping for {sourcePath}");
            Application.DoEvents();

            var undoneSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != recordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == expectedSectionRecordIndex &&
                           selectedObject?.RecordIndex == recordIndex &&
                           !selectedObject.Deleted &&
                           string.Equals(selectedObject.Title, expectedObjectTitle, StringComparison.Ordinal) &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), expectedUniqueId, StringComparison.Ordinal) &&
                           string.Equals(ReadSelectionPropertyValue(refreshedSelection, "HPOS"), expectedOriginalLayoutHpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal) &&
                           string.Equals(ReadSelectionPropertyValue(refreshedSelection, "VPOS"), expectedOriginalLayoutVpos.ToString(CultureInfo.InvariantCulture), StringComparison.Ordinal) &&
                           string.Equals(objectState, "Live", StringComparison.Ordinal) &&
                           snapToGridButton.Visible &&
                           snapToGridButton.Enabled &&
                           deleteButton.Visible &&
                           deleteButton.Enabled &&
                           !restoreButton.Visible &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == recordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == expectedSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(undoneSelection,
                $"real asset editor snap-to-grid smoke should preserve live section/object continuity after undoing snap for {sourcePath}");
            Expect(!control.CanHandleUndoCommand(),
                $"real asset editor snap-to-grid smoke should clear undo after restoring original geometry for {sourcePath}");

            var reloadedAfterUndo = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterUndo.Success && reloadedAfterUndo.Document is not null,
                $"real asset editor snap-to-grid smoke should reload restored on-disk state for {sourcePath}");
            if (reloadedAfterUndo.Success && reloadedAfterUndo.Document is not null)
            {
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterUndo.Document,
                    recordIndex,
                    "HPOS",
                    expectedOriginalRawHpos,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded undone real asset editor snap-to-grid snapshot should preserve original HPOS");
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterUndo.Document,
                    recordIndex,
                    "VPOS",
                    expectedOriginalRawVpos,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded undone real asset editor snap-to-grid snapshot should preserve original VPOS");

                var reloadedSection = reloadedAfterUndo.Document.ReportLayout?.Sections
                    .FirstOrDefault(candidate => candidate.RecordIndex == expectedSectionRecordIndex);
                var reloadedLayoutObject = reloadedSection?.Objects
                    .FirstOrDefault(candidate => candidate.RecordIndex == recordIndex);
                Expect(reloadedLayoutObject is not null,
                    $"reloaded undone real asset editor snap-to-grid snapshot should preserve layout object {recordIndex} for {sourcePath}");
                if (reloadedLayoutObject is not null)
                {
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "HPOS") == expectedOriginalLayoutHpos,
                        $"reloaded undone real asset editor snap-to-grid snapshot should expose layout HPOS={expectedOriginalLayoutHpos} for {sourcePath}");
                    Expect(TryGetReportLayoutObjectValue(reloadedLayoutObject, "VPOS") == expectedOriginalLayoutVpos,
                        $"reloaded undone real asset editor snap-to-grid snapshot should expose layout VPOS={expectedOriginalLayoutVpos} for {sourcePath}");
                }
            }

            TearDownForm(hostForm);
        }
        finally
        {
            try
            {
                if (Directory.Exists(tempRoot))
                {
                    Directory.Delete(tempRoot, recursive: true);
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }

    private static void SmokeAssetEditorDeletedDuplicateCommandWithRealAsset(
        string? sourcePath,
        int recordIndex,
        string expectedSectionTitle,
        int expectedSectionRecordIndex,
        string expectedObjectTitle,
        int expectedSectionCount,
        bool expectLabel,
        string expectedOriginalUniqueId,
        string expectedDuplicatedUniqueId)
    {
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
        {
            Console.WriteLine($"SKIP: {(string.IsNullOrWhiteSpace(sourcePath) ? "real asset editor deleted duplicate candidate" : sourcePath)} not found.");
            return;
        }

        var tempRoot = Path.Combine(Path.GetTempPath(), "CopperfinDesignerSmokeRealAssetEditorDeletedDuplicates-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tempRoot);
        var assetPath = CreateWritableAssetCopy(sourcePath!, tempRoot);
        var previousDuplicateUniqueId = Environment.GetEnvironmentVariable("COPPERFIN_DUPLICATE_OBJECT_UNIQUE_ID");

        try
        {
            Environment.SetEnvironmentVariable("COPPERFIN_DUPLICATE_OBJECT_UNIQUE_ID", expectedDuplicatedUniqueId);

            using var hostForm = new Form
            {
                Width = 1400,
                Height = 1000,
                ShowInTaskbar = false,
                StartPosition = FormStartPosition.Manual,
                Location = new Point(-32000, -32000)
            };

            using var control = new CopperfinAssetEditorControl
            {
                Dock = DockStyle.Fill
            };

            hostForm.Controls.Add(control);
            hostForm.Show();
            Application.DoEvents();
            control.LoadDocument(assetPath);

            var sectionListView = GetPrivateListView(control, "sectionListView");
            var objectListView = GetPrivateListView(control, "objectListView");
            var propertyGrid = GetPrivatePropertyGrid(control);
            var renameButton = GetPrivateButton(control, "renameObjectButton");
            var duplicateButton = GetPrivateButton(control, "duplicateObjectButton");
            var deleteButton = GetPrivateButton(control, "deleteObjectButton");
            var restoreButton = GetPrivateButton(control, "restoreObjectButton");
            var surface = FindDesignSurface(control) ?? throw new InvalidOperationException("Could not find shared report design surface for the real deleted-duplicate smoke.");

            var loaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => sectionListView.Items.Count > 0);
            Expect(loaded, $"real asset editor deleted-duplicate smoke should load section data for {sourcePath}");
            if (!loaded)
            {
                return;
            }

            foreach (ListViewItem item in sectionListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioReportSection section &&
                                section.RecordIndex == expectedSectionRecordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncExplorerSelection");
            Application.DoEvents();

            var objectLoaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => objectListView.Items.Cast<ListViewItem>()
                    .Any(item => item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                 snapshotObject.RecordIndex == recordIndex));
            Expect(objectLoaded, $"real asset editor deleted-duplicate smoke should surface object {recordIndex} for {sourcePath}");
            if (!objectLoaded)
            {
                return;
            }

            foreach (ListViewItem item in objectListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                snapshotObject.RecordIndex == recordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncSelectionFromList");
            Application.DoEvents();

            Expect(renameButton.Visible &&
                   renameButton.Enabled &&
                   duplicateButton.Visible &&
                   duplicateButton.Enabled &&
                   deleteButton.Visible &&
                   deleteButton.Enabled &&
                   !restoreButton.Visible &&
                   objectListView.Items.Count == 1 &&
                   propertyGrid.SelectedObject is CopperfinDesignerSelection initialSelection &&
                   initialSelection.RecordIndex == recordIndex,
                $"real asset editor deleted-duplicate smoke should start from a live object selection with rename, duplicate, and delete exposed for {sourcePath}");

            deleteButton.PerformClick();
            Application.DoEvents();

            var deletedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != recordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == expectedSectionRecordIndex &&
                           selectedSectionModel?.DeletedObjectCount == 1 &&
                           selectedObject?.RecordIndex == recordIndex &&
                           selectedObject.Deleted &&
                           string.Equals(selectedObject.Title, expectedObjectTitle, StringComparison.Ordinal) &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), expectedOriginalUniqueId, StringComparison.Ordinal) &&
                           string.Equals(objectState, "Deleted", StringComparison.Ordinal) &&
                           objectListView.Items.Count == 1 &&
                           renameButton.Visible &&
                           renameButton.Enabled &&
                           duplicateButton.Visible &&
                           duplicateButton.Enabled &&
                           !deleteButton.Visible &&
                           restoreButton.Visible &&
                           restoreButton.Enabled &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == recordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == expectedSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(deletedSelection,
                $"real asset editor deleted-duplicate smoke should preserve deleted selection continuity before duplicating for {sourcePath}");

            duplicateButton.PerformClick();
            Application.DoEvents();

            int duplicatedRecordIndex = -1;
            var duplicatedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex == recordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    var selectedUniqueId = selectedObject is null
                        ? null
                        : TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID");
                    if (string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                        selectedSectionModel?.RecordIndex == expectedSectionRecordIndex &&
                        selectedSectionModel?.DeletedObjectCount == 2 &&
                        selectedObject?.RecordIndex == refreshedSelection.RecordIndex &&
                        selectedObject.Deleted &&
                        string.Equals(selectedObject.Title, expectedObjectTitle, StringComparison.Ordinal) &&
                        string.Equals(selectedUniqueId, expectedDuplicatedUniqueId, StringComparison.Ordinal) &&
                        string.Equals(objectState, "Deleted", StringComparison.Ordinal) &&
                        objectListView.Items.Count == 2 &&
                        renameButton.Visible &&
                        renameButton.Enabled &&
                        duplicateButton.Visible &&
                        duplicateButton.Enabled &&
                        !deleteButton.Visible &&
                        restoreButton.Visible &&
                        restoreButton.Enabled &&
                        string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                        ReadPrivateNullableInt(surface, "selectedRecordIndex") == refreshedSelection.RecordIndex &&
                        ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == expectedSectionRecordIndex &&
                        !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected"))
                    {
                        duplicatedRecordIndex = refreshedSelection.RecordIndex;
                        return true;
                    }

                    return false;
                });
            Expect(duplicatedSelection,
                $"real asset editor deleted-duplicate smoke should preserve deleted section/object continuity after duplicating for {sourcePath}");
            Expect(!control.CanHandleUndoCommand(),
                $"real asset editor deleted-duplicate smoke should not expose undo after duplicating a deleted row for {sourcePath}");
            if (!duplicatedSelection)
            {
                return;
            }

            var reloadedAfterDuplicate = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterDuplicate.Success && reloadedAfterDuplicate.Document is not null,
                $"real asset editor deleted-duplicate smoke should reload duplicated deleted on-disk state for {sourcePath}");
            if (reloadedAfterDuplicate.Success && reloadedAfterDuplicate.Document is not null)
            {
                AssertRealAssetDeletedObjectSnapshot(
                    reloadedAfterDuplicate.Document,
                    recordIndex,
                    expectedOriginalUniqueId,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionRecordIndex,
                    expectedSectionCount,
                    expectLabel,
                    expectedVisibleSectionObjectCount: 2,
                    expectedDeletedSectionObjectCount: 2,
                    "reloaded real asset editor deleted-duplicate snapshot should preserve original deleted identity");
                AssertRealAssetDeletedObjectSnapshot(
                    reloadedAfterDuplicate.Document,
                    duplicatedRecordIndex,
                    expectedDuplicatedUniqueId,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionRecordIndex,
                    expectedSectionCount,
                    expectLabel,
                    expectedVisibleSectionObjectCount: 2,
                    expectedDeletedSectionObjectCount: 2,
                    "reloaded real asset editor deleted-duplicate snapshot should preserve duplicated deleted identity");
            }

            restoreButton.PerformClick();
            Application.DoEvents();

            var restoredSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != duplicatedRecordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == expectedSectionRecordIndex &&
                           selectedSectionModel?.DeletedObjectCount == 1 &&
                           selectedObject?.RecordIndex == duplicatedRecordIndex &&
                           !selectedObject.Deleted &&
                           string.Equals(selectedObject.Title, expectedObjectTitle, StringComparison.Ordinal) &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), expectedDuplicatedUniqueId, StringComparison.Ordinal) &&
                           string.Equals(objectState, "Live", StringComparison.Ordinal) &&
                           objectListView.Items.Count == 2 &&
                           renameButton.Visible &&
                           renameButton.Enabled &&
                           duplicateButton.Visible &&
                           duplicateButton.Enabled &&
                           deleteButton.Visible &&
                           deleteButton.Enabled &&
                           !restoreButton.Visible &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == duplicatedRecordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == expectedSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(restoredSelection,
                $"real asset editor deleted-duplicate smoke should preserve live continuity after restoring the duplicated row for {sourcePath}");

            var reloadedAfterRestore = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterRestore.Success && reloadedAfterRestore.Document is not null,
                $"real asset editor deleted-duplicate smoke should reload restored live state for {sourcePath}");
            if (reloadedAfterRestore.Success && reloadedAfterRestore.Document is not null)
            {
                AssertRealAssetDeletedObjectSnapshot(
                    reloadedAfterRestore.Document,
                    recordIndex,
                    expectedOriginalUniqueId,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionRecordIndex,
                    expectedSectionCount,
                    expectLabel,
                    expectedVisibleSectionObjectCount: 2,
                    "reloaded restored real asset editor deleted-duplicate snapshot should preserve the original deleted source row");
                AssertRealAssetRoundTripSnapshot(
                    reloadedAfterRestore.Document,
                    duplicatedRecordIndex,
                    "UNIQUEID",
                    expectedDuplicatedUniqueId,
                    expectedObjectTitle,
                    expectedSectionTitle,
                    expectedSectionCount,
                    expectLabel,
                    expectUnplacedObject: false,
                    "reloaded restored real asset editor deleted-duplicate snapshot should preserve duplicated live identity");
            }

            TearDownForm(hostForm);
        }
        finally
        {
            Environment.SetEnvironmentVariable("COPPERFIN_DUPLICATE_OBJECT_UNIQUE_ID", previousDuplicateUniqueId);

            try
            {
                if (Directory.Exists(tempRoot))
                {
                    Directory.Delete(tempRoot, recursive: true);
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }

    private static void SmokeRealAssetHostBackedReorderRoundTrip(
        string? sourcePath,
        int reorderedSourceRecordIndex,
        string reorderedSourceUniqueId,
        string reorderedSourceObjectTitle,
        int companionRecordIndex,
        string companionUniqueId,
        string companionObjectTitle,
        string expectedSectionTitle,
        int initialSectionRecordIndex,
        int reorderedSectionRecordIndex,
        int expectedSectionCount,
        int expectedSectionObjectCount,
        IReadOnlyList<int> expectedInitialSectionRecordOrder,
        IReadOnlyList<int> expectedReorderedSectionRecordOrder,
        int expectedReorderedRecordIndex,
        bool expectLabel)
    {
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
        {
            Console.WriteLine($"SKIP: {(string.IsNullOrWhiteSpace(sourcePath) ? "real live reorder candidate" : sourcePath)} not found.");
            return;
        }

        var tempRoot = Path.Combine(Path.GetTempPath(), "CopperfinDesignerSmokeRealAssetReorders-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tempRoot);
        var assetPath = CreateWritableAssetCopy(sourcePath!, tempRoot);

        try
        {
            var loaded = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(loaded.Success && loaded.Document is not null,
                $"real live reorder smoke should load snapshot data for {sourcePath}");
            if (!loaded.Success || loaded.Document is null)
            {
                return;
            }

            AssertRealAssetRoundTripSnapshot(
                loaded.Document,
                reorderedSourceRecordIndex,
                "UNIQUEID",
                reorderedSourceUniqueId,
                reorderedSourceObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"initial real live reorder snapshot should preserve the reordered-source identity");
            AssertRealAssetRoundTripSnapshot(
                loaded.Document,
                companionRecordIndex,
                "UNIQUEID",
                companionUniqueId,
                companionObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"initial real live reorder snapshot should preserve the companion identity");
            AssertRealAssetSectionObjectCount(
                loaded.Document,
                expectedSectionTitle,
                expectedSectionObjectCount,
                $"initial real live reorder snapshot should preserve section object counts");
            AssertRealAssetSectionRecordOrder(
                loaded.Document,
                expectedSectionTitle,
                initialSectionRecordIndex,
                expectedInitialSectionRecordOrder,
                $"initial real live reorder snapshot should preserve section record order");

            var reorderResult = CopperfinStudioSnapshotClient.TryReorderObject(
                assetPath,
                reorderedSourceRecordIndex,
                reorderedSourceUniqueId,
                "front");
            Expect(reorderResult.Success && reorderResult.Document is not null,
                $"real live reorder smoke should reorder record {reorderedSourceRecordIndex} for {sourcePath}");
            if (!reorderResult.Success || reorderResult.Document is null)
            {
                return;
            }

            AssertRealAssetRoundTripSnapshot(
                reorderResult.Document,
                expectedReorderedRecordIndex,
                "UNIQUEID",
                reorderedSourceUniqueId,
                reorderedSourceObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"reordered real live asset snapshot should preserve the reordered-source identity");
            AssertRealAssetRoundTripSnapshot(
                reorderResult.Document,
                companionRecordIndex,
                "UNIQUEID",
                companionUniqueId,
                companionObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"reordered real live asset snapshot should preserve the companion identity");
            AssertRealAssetSectionObjectCount(
                reorderResult.Document,
                expectedSectionTitle,
                expectedSectionObjectCount,
                $"reordered real live asset snapshot should preserve section object counts");
            AssertRealAssetSectionRecordOrder(
                reorderResult.Document,
                expectedSectionTitle,
                reorderedSectionRecordIndex,
                expectedReorderedSectionRecordOrder,
                $"reordered real live asset snapshot should preserve section record order");
            Expect(!reorderResult.Document.CommandUndoAvailable,
                $"real live reorder smoke should not expose command undo after reordering {sourcePath}");

            var reloadedAfterReorder = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterReorder.Success && reloadedAfterReorder.Document is not null,
                $"real live reorder smoke should reload reordered snapshot data for {sourcePath}");
            if (!reloadedAfterReorder.Success || reloadedAfterReorder.Document is null)
            {
                return;
            }

            AssertRealAssetRoundTripSnapshot(
                reloadedAfterReorder.Document,
                expectedReorderedRecordIndex,
                "UNIQUEID",
                reorderedSourceUniqueId,
                reorderedSourceObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"reloaded reordered real live asset snapshot should preserve the reordered-source identity");
            AssertRealAssetRoundTripSnapshot(
                reloadedAfterReorder.Document,
                companionRecordIndex,
                "UNIQUEID",
                companionUniqueId,
                companionObjectTitle,
                expectedSectionTitle,
                expectedSectionCount,
                expectLabel,
                expectUnplacedObject: false,
                $"reloaded reordered real live asset snapshot should preserve the companion identity");
            AssertRealAssetSectionObjectCount(
                reloadedAfterReorder.Document,
                expectedSectionTitle,
                expectedSectionObjectCount,
                $"reloaded reordered real live asset snapshot should preserve section object counts");
            AssertRealAssetSectionRecordOrder(
                reloadedAfterReorder.Document,
                expectedSectionTitle,
                reorderedSectionRecordIndex,
                expectedReorderedSectionRecordOrder,
                $"reloaded reordered real live asset snapshot should preserve section record order");
            Expect(!reloadedAfterReorder.Document.CommandUndoAvailable,
                $"reloaded real live reorder snapshot should not expose command undo for {sourcePath}");
        }
        finally
        {
            try
            {
                if (Directory.Exists(tempRoot))
                {
                    Directory.Delete(tempRoot, recursive: true);
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }

    private static void SmokeAssetEditorDeletedReorderCommandWithRealAsset(
        string? sourcePath,
        int reorderedSourceRecordIndex,
        string reorderedSourceUniqueId,
        string reorderedSourceObjectTitle,
        int companionRecordIndex,
        string companionUniqueId,
        string companionObjectTitle,
        string expectedSectionTitle,
        int initialSectionRecordIndex,
        int reorderedSectionRecordIndex,
        int expectedSectionCount,
        int expectedVisibleSectionObjectCount,
        int expectedReorderedRecordIndex,
        int expectedCompanionRecordIndex,
        bool expectLabel)
    {
        if (string.IsNullOrWhiteSpace(sourcePath) || !File.Exists(sourcePath))
        {
            Console.WriteLine($"SKIP: {(string.IsNullOrWhiteSpace(sourcePath) ? "real asset editor deleted reorder candidate" : sourcePath)} not found.");
            return;
        }

        var tempRoot = Path.Combine(Path.GetTempPath(), "CopperfinDesignerSmokeRealAssetEditorDeletedReorders-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(tempRoot);
        var assetPath = CreateWritableAssetCopy(sourcePath!, tempRoot);

        try
        {
            using var hostForm = new Form
            {
                Width = 1400,
                Height = 1000,
                ShowInTaskbar = false,
                StartPosition = FormStartPosition.Manual,
                Location = new Point(-32000, -32000)
            };

            using var control = new CopperfinAssetEditorControl
            {
                Dock = DockStyle.Fill
            };

            hostForm.Controls.Add(control);
            hostForm.Show();
            Application.DoEvents();
            control.LoadDocument(assetPath);

            var sectionListView = GetPrivateListView(control, "sectionListView");
            var objectListView = GetPrivateListView(control, "objectListView");
            var propertyGrid = GetPrivatePropertyGrid(control);
            var renameButton = GetPrivateButton(control, "renameObjectButton");
            var duplicateButton = GetPrivateButton(control, "duplicateObjectButton");
            var reorderFrontButton = GetPrivateButton(control, "reorderFrontObjectButton");
            var reorderBackButton = GetPrivateButton(control, "reorderBackObjectButton");
            var deleteButton = GetPrivateButton(control, "deleteObjectButton");
            var restoreButton = GetPrivateButton(control, "restoreObjectButton");
            var surface = FindDesignSurface(control) ?? throw new InvalidOperationException("Could not find shared report design surface for the real deleted-reorder smoke.");

            var loaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => sectionListView.Items.Count > 0);
            Expect(loaded, $"real asset editor deleted-reorder smoke should load section data for {sourcePath}");
            if (!loaded)
            {
                return;
            }

            foreach (ListViewItem item in sectionListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioReportSection section &&
                                section.RecordIndex == initialSectionRecordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncExplorerSelection");
            Application.DoEvents();

            var objectsLoaded = WaitUntil(
                TimeSpan.FromSeconds(8),
                () => objectListView.Items.Cast<ListViewItem>().Any(item =>
                          item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                          (snapshotObject.RecordIndex == reorderedSourceRecordIndex || snapshotObject.RecordIndex == companionRecordIndex)));
            Expect(objectsLoaded, $"real asset editor deleted-reorder smoke should surface source objects for {sourcePath}");
            if (!objectsLoaded)
            {
                return;
            }

            foreach (ListViewItem item in objectListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                snapshotObject.RecordIndex == reorderedSourceRecordIndex;
            }

            InvokeAssetEditorVoid(control, "SyncSelectionFromList");
            Application.DoEvents();

            Expect(renameButton.Visible &&
                   renameButton.Enabled &&
                   duplicateButton.Visible &&
                   duplicateButton.Enabled &&
                   reorderFrontButton.Visible &&
                   reorderFrontButton.Enabled &&
                   reorderBackButton.Visible &&
                   reorderBackButton.Enabled &&
                   deleteButton.Visible &&
                   deleteButton.Enabled &&
                   !restoreButton.Visible &&
                   objectListView.Items.Count == expectedVisibleSectionObjectCount &&
                   propertyGrid.SelectedObject is CopperfinDesignerSelection initialSelection &&
                   initialSelection.RecordIndex == reorderedSourceRecordIndex,
                $"real asset editor deleted-reorder smoke should start from a live object selection with reorder commands exposed for {sourcePath}");

            deleteButton.PerformClick();
            Application.DoEvents();

            var firstDeletedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != reorderedSourceRecordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == initialSectionRecordIndex &&
                           selectedSectionModel?.DeletedObjectCount == 1 &&
                           selectedObject?.RecordIndex == reorderedSourceRecordIndex &&
                           selectedObject.Deleted &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), reorderedSourceUniqueId, StringComparison.Ordinal) &&
                           string.Equals(objectState, "Deleted", StringComparison.Ordinal) &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == reorderedSourceRecordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == initialSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(firstDeletedSelection,
                $"real asset editor deleted-reorder smoke should preserve deleted selection continuity after the first delete for {sourcePath}");
            if (!firstDeletedSelection)
            {
                return;
            }

            foreach (ListViewItem item in objectListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                snapshotObject.RecordIndex == companionRecordIndex &&
                                !snapshotObject.Deleted;
            }

            InvokeAssetEditorVoid(control, "SyncSelectionFromList");
            Application.DoEvents();
            deleteButton.PerformClick();
            Application.DoEvents();

            var secondDeletedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != companionRecordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == initialSectionRecordIndex &&
                           selectedSectionModel?.DeletedObjectCount == 2 &&
                           selectedObject?.RecordIndex == companionRecordIndex &&
                           selectedObject.Deleted &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), companionUniqueId, StringComparison.Ordinal) &&
                           string.Equals(objectState, "Deleted", StringComparison.Ordinal) &&
                           reorderFrontButton.Visible &&
                           reorderFrontButton.Enabled &&
                           reorderBackButton.Visible &&
                           reorderBackButton.Enabled &&
                           !deleteButton.Visible &&
                           restoreButton.Visible &&
                           restoreButton.Enabled &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == companionRecordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == initialSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(secondDeletedSelection,
                $"real asset editor deleted-reorder smoke should preserve deleted selection continuity before reordering for {sourcePath}");
            if (!secondDeletedSelection)
            {
                return;
            }

            foreach (ListViewItem item in objectListView.Items)
            {
                item.Selected = item.Tag is CopperfinStudioSnapshotObject snapshotObject &&
                                snapshotObject.RecordIndex == reorderedSourceRecordIndex &&
                                snapshotObject.Deleted;
            }

            InvokeAssetEditorVoid(control, "SyncSelectionFromList");
            Application.DoEvents();
            reorderFrontButton.PerformClick();
            Application.DoEvents();

            var reorderedSelection = WaitUntil(
                TimeSpan.FromSeconds(8),
                () =>
                {
                    if (propertyGrid.SelectedObject is not CopperfinDesignerSelection refreshedSelection ||
                        refreshedSelection.RecordIndex != expectedReorderedRecordIndex)
                    {
                        return false;
                    }

                    var selectedSection = sectionListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault();
                    var selectedSectionModel = selectedSection?.Tag as CopperfinStudioReportSection;
                    var selectedObject = objectListView.SelectedItems.Cast<ListViewItem>().FirstOrDefault()?.Tag as CopperfinStudioSnapshotObject;
                    var objectState = TypeDescriptor.GetProperties(refreshedSelection)["OBJECTSTATE"]?.GetValue(refreshedSelection)?.ToString();
                    return string.Equals(selectedSection?.Text, expectedSectionTitle, StringComparison.OrdinalIgnoreCase) &&
                           selectedSectionModel?.RecordIndex == reorderedSectionRecordIndex &&
                           selectedSectionModel?.DeletedObjectCount == 2 &&
                           selectedObject?.RecordIndex == expectedReorderedRecordIndex &&
                           selectedObject.Deleted &&
                           string.Equals(TryGetSnapshotObjectPropertyValue(selectedObject, "UNIQUEID"), reorderedSourceUniqueId, StringComparison.Ordinal) &&
                           string.Equals(objectState, "Deleted", StringComparison.Ordinal) &&
                           reorderFrontButton.Visible &&
                           reorderFrontButton.Enabled &&
                           reorderBackButton.Visible &&
                           reorderBackButton.Enabled &&
                           !deleteButton.Visible &&
                           restoreButton.Visible &&
                           restoreButton.Enabled &&
                           string.Equals(ReadPrivateStringField(surface, "assetFamily"), expectLabel ? "label" : "report", StringComparison.Ordinal) &&
                           ReadPrivateNullableInt(surface, "selectedRecordIndex") == expectedReorderedRecordIndex &&
                           ReadPrivateNullableInt(surface, "selectedReportSectionRecordIndex") == reorderedSectionRecordIndex &&
                           !ReadPrivateBoolField(surface, "unplacedReportObjectsSelected");
                });
            Expect(reorderedSelection,
                $"real asset editor deleted-reorder smoke should preserve deleted section/object continuity after reordering for {sourcePath}");
            Expect(!control.CanHandleUndoCommand(),
                $"real asset editor deleted-reorder smoke should not expose undo after reordering a deleted row for {sourcePath}");
            if (!reorderedSelection)
            {
                return;
            }

            var reloadedAfterReorder = CopperfinStudioSnapshotClient.TryLoad(assetPath);
            Expect(reloadedAfterReorder.Success && reloadedAfterReorder.Document is not null,
                $"real asset editor deleted-reorder smoke should reload reordered deleted on-disk state for {sourcePath}");
            if (reloadedAfterReorder.Success && reloadedAfterReorder.Document is not null)
            {
                AssertRealAssetDeletedObjectSnapshot(
                    reloadedAfterReorder.Document,
                    expectedReorderedRecordIndex,
                    reorderedSourceUniqueId,
                    reorderedSourceObjectTitle,
                    expectedSectionTitle,
                    reorderedSectionRecordIndex,
                    expectedSectionCount,
                    expectLabel,
                    expectedVisibleSectionObjectCount,
                    expectedDeletedSectionObjectCount: 2,
                    "reloaded real asset editor deleted-reorder snapshot should preserve the reordered-source identity",
                    assertTitles: false);
                AssertRealAssetDeletedObjectSnapshot(
                    reloadedAfterReorder.Document,
                    expectedCompanionRecordIndex,
                    companionUniqueId,
                    companionObjectTitle,
                    expectedSectionTitle,
                    reorderedSectionRecordIndex,
                    expectedSectionCount,
                    expectLabel,
                    expectedVisibleSectionObjectCount,
                    expectedDeletedSectionObjectCount: 2,
                    "reloaded real asset editor deleted-reorder snapshot should preserve the companion identity");
                AssertRealAssetDeletedObjectOrder(
                    reloadedAfterReorder.Document,
                    reorderedSectionRecordIndex,
                    new[] { expectedReorderedRecordIndex, expectedCompanionRecordIndex },
                    new[] { reorderedSourceUniqueId, companionUniqueId },
                    "reloaded real asset editor deleted-reorder snapshot should preserve deleted-row order");
            }
        }
        finally
        {
            try
            {
                if (Directory.Exists(tempRoot))
                {
                    Directory.Delete(tempRoot, recursive: true);
                }
            }
            catch (IOException)
            {
            }
            catch (UnauthorizedAccessException)
            {
            }
        }
    }

    private static void SmokeAssetEditorReorderCommandWithRealAsset(
        string? sourcePath,
        int reorderedSourceRecordIndex,
        string reorderedSourceUniqueId,
        string reorderedSourceObjectTitle,
        int companionRecordIndex,
        string companionUniqueId,
        string companionObjectTitle,
